class Solution {
    void collect(TreeNode* node, unordered_set<int>& values) {
        if (!node) {
            return;
        }
        values.insert(node->val);
        collect(node->left, values);
        collect(node->right, values);
    }

    bool search(TreeNode* node, int target,
                const unordered_set<int>& values) {
        if (!node) {
            return false;
        }
        if (values.count(target - node->val)) {
            return true;
        }
        return search(node->left, target, values)
            || search(node->right, target, values);
    }

public:
    bool twoSumBSTs(TreeNode* root1, TreeNode* root2, int target) {
        unordered_set<int> values;
        collect(root1, values);
        return search(root2, target, values);
    }
};
